package vn.vinhkhang.warehouse;
import java.util.*;import java.io.*;import java.math.BigDecimal;import java.text.Normalizer;import java.security.MessageDigest;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.poi.ss.usermodel.*;import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/excel-import")
public class ExcelImports {
 private final Api core;private final JdbcTemplate db;private final ObjectMapper json;private final TransactionTemplate tx;
 public ExcelImports(Api core,JdbcTemplate db,ObjectMapper json,PlatformTransactionManager manager){this.core=core;this.db=db;this.json=json;tx=new TransactionTemplate(manager);}
 @ExceptionHandler(Api.Problem.class) public org.springframework.http.ResponseEntity<?> problem(Api.Problem e){return org.springframework.http.ResponseEntity.status(e.status).body(Map.of("message",e.getMessage()));}
 static String key(String s){return Normalizer.normalize(s,Normalizer.Form.NFC).strip().toLowerCase(Locale.ROOT).replaceAll("\\s+"," ");}
 void authorize(String t,String kind){var u=core.user(t,true);if(!Set.of("parts","bom").contains(kind))throw new Api.Problem(400,"Mục nhập Excel không hợp lệ");if(kind.equals("bom")){core.admin(t);if(AccountKinds.get(db,u.id()).equals("STORE"))throw new Api.Problem(403,"Tài khoản cửa hàng không dùng BOM");}}
 static String cell(Row row,int c){var v=row.getCell(c);if(v==null)return "";if(v.getCellType()==CellType.FORMULA)throw new Api.Problem(400,"Không dùng công thức; anh nhập giá trị trực tiếp");if(v.getCellType()==CellType.ERROR)throw new Api.Problem(400,"Ô Excel đang lỗi");return new DataFormatter(Locale.ROOT).formatCellValue(v).strip();}
 Map<String,Object> model(List<Map<String,Object>> models,String value){var found=models.stream().filter(m->key(Objects.toString(m.get("CODE"))).equals(key(value))||key(Objects.toString(m.get("NAME"))).equals(key(value))).toList();if(found.size()!=1)throw new Api.Problem(400,"Mẫu xe không tồn tại hoặc không rõ: "+value);return found.getFirst();}
 Map<String,Object> plan(String t,String kind,Map<String,Object> body){authorize(t,kind);String encoded=Objects.toString(body.get("file"),"");if(encoded.length()>12_000_000)throw new Api.Problem(400,"File tối đa 8 MB");byte[] bytes;try{bytes=Base64.getDecoder().decode(encoded);}catch(Exception e){throw new Api.Problem(400,"File Excel không hợp lệ");}if(bytes.length==0||bytes.length>8_000_000)throw new Api.Problem(400,"File tối đa 8 MB");
  var parts=db.queryForList("SELECT id,code,name,unit,deleted,color_parent_id FROM parts ORDER BY id");var models=db.queryForList("SELECT id,code,name FROM vehicle_models WHERE deleted=FALSE ORDER BY id");var versions=db.queryForList("SELECT model_id,COALESCE(MAX(version),0)+1 next_version FROM bom_versions GROUP BY model_id ORDER BY model_id");
  var rows=new ArrayList<Map<String,Object>>();var errors=new ArrayList<String>();var codes=new HashSet<String>();var names=new HashSet<String>();long next=1;for(var p:parts){codes.add(key(p.get("CODE").toString()));names.add(key(p.get("NAME").toString())+"|"+key(p.get("UNIT").toString()));String code=p.get("CODE").toString().toUpperCase(Locale.ROOT);if(code.matches("LK[0-9]{1,9}"))next=Math.max(next,Long.parseLong(code.substring(2))+1);}var seen=new HashSet<String>();var usedNames=new HashSet<String>();
  try(var book=new XSSFWorkbook(new ByteArrayInputStream(bytes))){String sheetName=kind.equals("parts")?"Linh kien":"BOM";var sh=book.getSheet(sheetName);if(sh==null)throw new Api.Problem(400,"Thiếu trang "+sheetName+". Anh tải mẫu rồi điền vào đúng trang");if(sh.getLastRowNum()>1000)throw new Api.Problem(400,"Tối đa 1000 dòng mỗi file");String[] headers=kind.equals("parts")?new String[]{"Mã linh kiện","Tên linh kiện","Đơn vị","Mẫu xe phân màu"}:new String[]{"Mẫu xe","Mã linh kiện","Tên linh kiện","Số lượng / xe"};for(int c=0;c<headers.length;c++)if(sh.getRow(0)==null||!key(cell(sh.getRow(0),c)).equals(key(headers[c])))throw new Api.Problem(400,"Cột "+(c+1)+" phải là “"+headers[c]+"”. Anh dùng file mẫu");
   for(int r=1;r<=sh.getLastRowNum();r++){Row row=sh.getRow(r);if(row==null)continue;var out=new LinkedHashMap<String,Object>();out.put("row",r+1);try{String[] v=new String[4];for(int c=0;c<4;c++)v[c]=cell(row,c);if(Arrays.stream(v).allMatch(String::isBlank))continue;
    if(kind.equals("parts")){String code=v[0];if(code.isBlank()){while(codes.contains(key("LK"+next)))next++;code="LK"+next++;}if(code.length()>40||v[1].isBlank()||v[1].length()>200||v[2].isBlank()||v[2].length()>30)throw new Api.Problem(400,"Cần tên, đơn vị; mã tối đa 40, tên 200, đơn vị 30 ký tự");if(!codes.add(key(code)))throw new Api.Problem(400,"Mã đã có hoặc bị trùng: "+code);String nameKey=key(v[1])+"|"+key(v[2]);if(names.contains(nameKey)||!usedNames.add(nameKey))throw new Api.Problem(400,"Tên và đơn vị đã có hoặc bị trùng; không ghi đè linh kiện cũ");var colorIds=new ArrayList<Long>();var colorNames=new ArrayList<String>();if(!v[3].isBlank())for(String value:v[3].split("[;,]")){var m=model(models,value);long id=((Number)m.get("ID")).longValue();if(colorIds.contains(id))throw new Api.Problem(400,"Mẫu xe phân màu bị trùng");colorIds.add(id);colorNames.add(m.get("CODE").toString());}out.put("code",code);out.put("name",v[1]);out.put("unit",v[2]);out.put("color_models",colorIds);out.put("color_names",String.join("; ",colorNames));
    }else{var m=model(models,v[0]);long modelId=((Number)m.get("ID")).longValue();if(v[1].isBlank()&&v[2].isBlank())throw new Api.Problem(400,"Điền mã hoặc tên linh kiện");var found=parts.stream().filter(p->!Boolean.TRUE.equals(p.get("DELETED"))&&p.get("COLOR_PARENT_ID")==null&&(v[1].isBlank()?key(p.get("NAME").toString()).equals(key(v[2])):key(p.get("CODE").toString()).equals(key(v[1])))).toList();if(found.size()!=1)throw new Api.Problem(400,"Linh kiện chưa có hoặc tên không rõ; anh nhập Linh kiện trước rồi dùng mã gốc");var p=found.getFirst();if(!v[2].isBlank()&&!key(v[2]).equals(key(p.get("NAME").toString())))throw new Api.Problem(400,"Tên không khớp mã linh kiện");long partId=((Number)p.get("ID")).longValue();if(!seen.add(modelId+":"+partId))throw new Api.Problem(400,"Một linh kiện chỉ có một dòng trong mỗi mẫu xe");BigDecimal qty;try{String number=v[3];if(number.contains(",")&&!number.contains("."))number=number.replace(',','.');qty=new BigDecimal(number);}catch(Exception e){throw new Api.Problem(400,"Số lượng phải là số dương, ví dụ 1 hoặc 0,5");}if(qty.signum()<=0||qty.scale()>3||qty.compareTo(new BigDecimal("1000000"))>0)throw new Api.Problem(400,"Số lượng phải lớn hơn 0, tối đa 3 chữ số thập phân và không quá 1000000");long version=versions.stream().filter(x->((Number)x.get("MODEL_ID")).longValue()==modelId).map(x->((Number)x.get("NEXT_VERSION")).longValue()).findFirst().orElse(1L);out.put("model_id",modelId);out.put("model",m.get("CODE"));out.put("part_id",partId);out.put("code",p.get("CODE"));out.put("name",p.get("NAME"));out.put("quantity",qty);out.put("version",version);
    }rows.add(out);
   }catch(Api.Problem e){errors.add("Dòng "+(r+1)+": "+e.getMessage());}}
  }catch(Api.Problem e){throw e;}catch(Exception e){throw new Api.Problem(400,"Không đọc được file .xlsx; file có thể bị lỗi hoặc quá lớn");}if(rows.isEmpty()&&errors.isEmpty())errors.add("Chưa có dữ liệu. Điền từ dòng 2 ở trang dữ liệu; ví dụ trong trang Hướng dẫn không được nhập");
  String fingerprint;try{fingerprint=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(List.of(kind,rows,errors,parts,models,versions))));}catch(Exception e){throw new Api.Problem(500,"Không kiểm tra được dữ liệu");}return Map.of("rows",rows,"errors",errors,"fingerprint",fingerprint,"valid",errors.isEmpty(),"note",kind.equals("bom")?"Tạo phiên bản BOM mới cho từng mẫu xe; chỉ gồm các dòng trong file. BOM và lệnh sản xuất cũ giữ nguyên.":"Chỉ tạo linh kiện mới; không ghi đè danh mục và không nhập số lượng tồn kho.");
 }
 @PostMapping("/{kind}/preview") public Object preview(@RequestHeader("Authorization") String t,@PathVariable String kind,@RequestBody Map<String,Object> body){return plan(t,kind,body);}
 @PostMapping("/{kind}/commit") public synchronized Object commit(@RequestHeader("Authorization") String t,@PathVariable String kind,@RequestBody Map<String,Object> body){authorize(t,kind);if(!"NHAP EXCEL".equals(body.get("confirmation")))throw new Api.Problem(400,"Chưa xác nhận nhập Excel");return tx.execute(status->{var p=plan(t,kind,body);if(!Boolean.TRUE.equals(p.get("valid")))throw new Api.Problem(400,"Sửa các dòng lỗi trước khi nhập");if(!Objects.equals(p.get("fingerprint"),body.get("fingerprint")))throw new Api.Problem(409,"Danh mục đã thay đổi. Anh xem trước lại để kiểm tra mã và BOM");@SuppressWarnings("unchecked") var rows=(List<Map<String,Object>>)p.get("rows");var ids=new ArrayList<Long>();if(kind.equals("parts")){for(var row:rows)ids.add(core.create("parts",t,row).get("id"));}else{var groups=new LinkedHashMap<Long,List<Map<String,Object>>>();for(var row:rows)groups.computeIfAbsent(((Number)row.get("model_id")).longValue(),x->new ArrayList<>()).add(row);for(var group:groups.entrySet()){var first=group.getValue().getFirst();var lines=group.getValue().stream().map(r->Map.<String,Object>of("part_id",r.get("part_id"),"quantity",r.get("quantity"))).toList();ids.add(core.bom(t,Map.of("model_id",group.getKey(),"version",first.get("version"),"lines",lines)).get("id"));}}return Map.of("imported",ids.size(),"rows",rows.size(),"ids",ids);});}
}

